import heapq

def k_nearest_neighbors(points, k):
    max_heap = []
    for x, y in points:
        dist_sq = x*x + y*y
        if len(max_heap) < k:
            heapq.heappush(max_heap, (-dist_sq, (x, y)))
        elif dist_sq < -max_heap[0][0]:
            heapq.heapreplace(max_heap, (-dist_sq, (x, y)))
    result = sorted(max_heap, key=lambda item: -item[0])
    return [item[1] for item in result]

