import heapq

class EmergencyTriage:
    def __init__(self):
        self.counter = 0
        self.pq = []

    def admit(self, patient_id, severity):
        heapq.heappush(self.pq, (severity, self.counter, patient_id))
        self.counter += 1

    def treat_next(self):
        if not self.pq:
            raise IndexError('no patients in triage')
        severity, _, patient_id = heapq.heappop(self.pq)
        return (patient_id, severity)

import heapq

def max_non_overlapping_meetings(intervals):
    if not intervals:
        return 0, []
    intervals.sort(key=lambda x: x[0])
    selected = []
    pq = []
    for s, e in intervals:
        while pq and pq[0] <= s:
            heapq.heappop(pq)
        heapq.heappush(pq, e)
        if len(pq) == 1:
            selected.append((s, e))
        else:
            selected[-1] = (selected[-1][0], e)
    return len(selected), selected
